'use client';

import { useState, useEffect } from 'react';
import { useRouter, usePathname, useParams } from 'next/navigation';
import { useSession } from '@/lib/auth-client';
import { Header } from '@/components/header';
import { Project } from '@/lib/types';

export default function DashboardLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const router = useRouter();
  const pathname = usePathname();
  const params = useParams();
  const { data: session, isPending, error } = useSession();
  const [currentProject, setCurrentProject] = useState<Project | null>(null);

  console.log('DashboardLayout: Session state:', { session, isPending, error });

  const loadProject = async (projectId: string) => {
    try {
      const response = await fetch('/api/projects');
      if (response.ok) {
        const projects = await response.json();
        const project = projects.find((p: Project) => p.id === projectId);
        if (project) {
          setCurrentProject(project);
        }
      }
    } catch (error) {
      console.error('Error loading project:', error);
    }
  };

  const handleProjectChange = (project: Project) => {
    router.push(`/app/projects/${project.id}`);
  };

  // Redirect to auth if not logged in
  useEffect(() => {
    if (!isPending && !session) {
      console.log('DashboardLayout: No session found');
      // router.push('/auth/sign-in'); // Disabled for debugging
    }
  }, [session, isPending, router]);

  // Load current project if on project page
  useEffect(() => {
    if (params.id) {
      loadProject(params.id as string);
    } else {
      setCurrentProject(null);
    }
  }, [params.id]);

  // Check if we're on a project page to show project selector
  const showProjectSelector = pathname?.startsWith('/app/projects/');

  if (isPending) {
    return (
      <div className="flex items-center justify-center h-screen">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
      </div>
    );
  }

  if (!session) {
    return (
      <div className="flex flex-col items-center justify-center h-screen gap-6 p-8 bg-zinc-50 dark:bg-zinc-950">
        <div className="max-w-md w-full bg-white dark:bg-zinc-900 p-8 rounded-lg shadow-lg text-center">
          <h1 className="text-2xl font-bold text-red-600 mb-4">Access Denied</h1>
          <p className="text-zinc-600 dark:text-zinc-400 mb-6">
            We couldn't detect an active session. This might be because:
            <ul className="list-disc text-left mt-4 ml-4 space-y-2 text-sm">
              <li>Cookies are disabled or blocked</li>
              <li>The session expired</li>
              <li>There is a configuration mismatch between client/server</li>
            </ul>
          </p>

          <div className="bg-gray-100 dark:bg-gray-800 p-4 rounded text-left text-xs font-mono mb-6 overflow-auto">
            <p><strong>Error:</strong> {error ? error.message : 'None'}</p>
            <p><strong>Cookie Present:</strong> {typeof document !== 'undefined' ? (document.cookie ? 'Yes' : 'No') : 'Unknown'}</p>
          </div>

          <div className="flex flex-col gap-3">
            <button
              onClick={() => window.location.reload()}
              className="w-full px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700 font-medium"
            >
              Reload Page
            </button>
            <button
              onClick={() => router.push('/auth/sign-in')}
              className="w-full px-4 py-2 border border-zinc-300 dark:border-zinc-700 rounded hover:bg-zinc-100 dark:hover:bg-zinc-800 font-medium"
            >
              Back to Sign In
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col h-screen">
      <Header
        showProjectSelector={showProjectSelector}
        currentProject={currentProject}
        onProjectChange={handleProjectChange}
      />
      {children}
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Plus, X, Loader2 } from 'lucide-react';
import { Project } from '@/lib/types';

export default function DashboardPage() {
  const router = useRouter();
  const [projects, setProjects] = useState<Project[]>([]);
  const [isLoading, setIsLoading] = useState(true);
  const [showNameInput, setShowNameInput] = useState(false);
  const [projectName, setProjectName] = useState('');
  const [isCreating, setIsCreating] = useState(false);

  // Load projects
  useEffect(() => {
    loadProjects();
  }, []);

  const loadProjects = async () => {
    try {
      const response = await fetch('/api/projects');
      if (response.ok) {
        const data = await response.json();
        setProjects(data);
      }
    } catch (error) {
      console.error('Error loading projects:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCreateProject = async () => {
    if (!projectName.trim() || isCreating) return;

    setIsCreating(true);
    try {
      const response = await fetch('/api/projects', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ name: projectName.trim() }),
      });
      if (response.ok) {
        const project = await response.json();
        setShowNameInput(false);
        setProjectName('');
        router.push(`/app/projects/${project.id}`);
      }
    } catch (error) {
      console.error('Error creating project:', error);
      setIsCreating(false);
    }
  };

  const handleKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter') {
      handleCreateProject();
    } else if (e.key === 'Escape') {
      setShowNameInput(false);
      setProjectName('');
    }
  };

  return (
    <div className="flex-1 bg-zinc-50 dark:bg-zinc-950 overflow-auto">
      <main className="container mx-auto px-4 py-8">
        <div className="flex items-center justify-between mb-8">
          <div>
            <h2 className="text-3xl font-bold mb-2">Your Projects</h2>
            <p className="text-zinc-600 dark:text-zinc-400">
              Create and manage your design projects
            </p>
          </div>

          {showNameInput ? (
            <div className="flex items-center gap-2">
              <Input
                type="text"
                placeholder="Project name..."
                value={projectName}
                onChange={(e) => setProjectName(e.target.value)}
                onKeyDown={handleKeyDown}
                className="w-64"
                autoFocus
              />
              <Button onClick={handleCreateProject} disabled={!projectName.trim() || isCreating}>
                {isCreating ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Creating...
                  </>
                ) : (
                  'Create'
                )}
              </Button>
              <Button
                variant="ghost"
                size="icon"
                onClick={() => {
                  setShowNameInput(false);
                  setProjectName('');
                }}
              >
                <X className="h-4 w-4" />
              </Button>
            </div>
          ) : (
            <Button onClick={() => setShowNameInput(true)} size="lg">
              <Plus className="h-5 w-5 mr-2" />
              New Project
            </Button>
          )}
        </div>

        {isLoading ? (
          <div className="flex items-center justify-center py-12">
            <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
          </div>
        ) : projects.length === 0 ? (
          <div className="text-center py-12">
            <div className="inline-flex items-center justify-center w-16 h-16 rounded-full bg-zinc-100 dark:bg-zinc-800 mb-4">
              <Plus className="h-8 w-8 text-zinc-400" />
            </div>
            <h3 className="text-xl font-semibold mb-2">No projects yet</h3>
            <p className="text-zinc-600 dark:text-zinc-400 mb-4">
              Create your first project to get started
            </p>
            <Button onClick={handleCreateProject}>
              <Plus className="h-4 w-4 mr-2" />
              Create Project
            </Button>
          </div>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {projects.map((project) => (
              <div
                key={project.id}
                onClick={() => router.push(`/app/projects/${project.id}`)}
                className="group cursor-pointer bg-white dark:bg-zinc-900 rounded-lg border border-zinc-200 dark:border-zinc-800 p-3 hover:border-zinc-300 dark:hover:border-zinc-700 transition-colors"
              >
                <div className="aspect-video bg-zinc-100 dark:bg-zinc-800 rounded-md mb-2 flex items-center justify-center overflow-hidden">
                  {(project as any).thumbnail ? (
                    <img
                      src={(project as any).thumbnail}
                      alt={project.name}
                      className="w-full h-full object-cover"
                    />
                  ) : (
                    <div className="text-zinc-400 text-sm">No preview</div>
                  )}
                </div>
                <div className="flex items-start justify-between mt-2">
                  <h3 className="text-md font-semibold group-hover:text-blue-600 dark:group-hover:text-blue-400 transition-colors">
                    {project.name}
                  </h3>
                </div>
                <div className="text-sm text-zinc-500 dark:text-zinc-400 mb-2">
                  Updated {new Date(project.updatedAt).toLocaleDateString()}
                </div>
              </div>
            ))}
          </div>
        )}
      </main>
    </div>
  );
}

