'use client';

import { useState, useEffect } from 'react';
import { useRouter, useParams } from 'next/navigation';
import { ChatInterface } from '@/components/chat-interface';
import { HTMLViewer } from '@/components/html-viewer';
import { ResizablePanelGroup, ResizablePanel, ResizableHandle } from '@/components/ui/resizable';
import { Project } from '@/lib/types';

export default function ProjectPage() {
  const router = useRouter();
  const params = useParams();
  const [currentProject, setCurrentProject] = useState<Project | null>(null);
  const [selectedPageIndex, setSelectedPageIndex] = useState(0);
  const [artworkState, setArtworkState] = useState({
    width: 800,
    height: 600,
    versions: [] as Array<{ html: string; timestamp: number; googleFonts?: string[] }>,
    currentVersion: -1,
  });
  const [resetKey, setResetKey] = useState(0);

  // Load project by ID
  useEffect(() => {
    if (params.id) {
      loadProject(params.id as string);
      loadArtwork(params.id as string);
    }
  }, [params.id]);

  const loadProject = async (projectId: string) => {
    try {
      const response = await fetch('/api/projects');
      if (response.ok) {
        const projects = await response.json();
        const project = projects.find((p: Project) => p.id === projectId);
        if (project) {
          setCurrentProject(project);
        } else {
          router.push('/');
        }
      }
    } catch (error) {
      console.error('Error loading project:', error);
    }
  };

  const loadArtwork = async (projectId: string) => {
    try {
      const response = await fetch(`/api/artwork?projectId=${projectId}`);
      if (response.ok) {
        const artwork = await response.json();
        setArtworkState({
          width: artwork.width,
          height: artwork.height,
          versions: artwork.versions || [],
          currentVersion: artwork.currentVersion,
        });
      }
    } catch (error) {
      console.error('Error loading artwork:', error);
    }
  };

  // Reset everything when project changes
  const handleProjectChange = (project: Project) => {
    router.push(`/projects/${project.id}`);
  };

  const handleArtworkUpdate = async () => {
    // Reload artwork from API to get latest version with fonts
    if (params.id) {
      await loadArtwork(params.id as string);
    }
  };

  if (!currentProject) {
    return (
      <div className="flex items-center justify-center h-full">
        <div className="animate-spin rounded-full h-8 w-8 border-b-2 border-gray-900"></div>
      </div>
    );
  }

  return (
    <ResizablePanelGroup direction="horizontal" className="flex-1">
      {/* Chat Panel */}
      <ResizablePanel defaultSize={50} minSize={30}>
        <ChatInterface
          key={resetKey}
          projectId={currentProject.id}
          selectedPageIndex={selectedPageIndex}
          onArtworkUpdate={handleArtworkUpdate}
        />
      </ResizablePanel>

      <ResizableHandle withHandle />

      {/* Artwork Panel */}
      <ResizablePanel defaultSize={50} minSize={30}>
        <div className="h-full p-4">
          <HTMLViewer
            width={artworkState.width}
            height={artworkState.height}
            versions={artworkState.versions}
            currentVersion={artworkState.currentVersion}
            selectedPageIndex={selectedPageIndex}
            onSelectedPageIndexChange={setSelectedPageIndex}
          />
        </div>
      </ResizablePanel>
    </ResizablePanelGroup>
  );
}

'use client';

import { SignInForm } from '@/components/auth/sign-in-form';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useState } from 'react';
import { authClient } from '@/lib/auth-client';
import { Loader2 } from 'lucide-react';

export default function SignInPage() {
    const router = useRouter();
    const [debugInfo, setDebugInfo] = useState<{
        status: 'verifying' | 'success' | 'failed' | 'error';
        message: string;
        details?: string;
    } | null>(null);

    return (
        <div className="flex items-center justify-center min-h-screen bg-zinc-50 dark:bg-zinc-950">
            <div className="w-full max-w-md p-8 bg-white dark:bg-zinc-900 rounded-lg shadow-lg relative">
                <h1 className="text-2xl font-bold text-center mb-6">Sign In to Artiste</h1>

                <SignInForm onSuccess={async () => {
                    setDebugInfo({ status: 'verifying', message: 'Sign in successful. Verifying session...' });
                    try {
                        // Check if session exists via API
                        const res = await fetch('/api/auth/get-session');
                        const data = await res.json();

                        // Check via client
                        const clientSession = await authClient.getSession();
                        const cookie = document.cookie;

                        if (data?.session || clientSession?.data?.session) {
                            setDebugInfo({
                                status: 'success',
                                message: 'Session verified! Redirecting to dashboard...',
                                details: `User: ${data?.user?.email || clientSession?.data?.user?.email}`
                            });
                            setTimeout(() => {
                                window.location.href = '/app';
                            }, 1500);
                        } else {
                            setDebugInfo({
                                status: 'failed',
                                message: 'Login successful but session is missing.',
                                details: `
API Session: ${JSON.stringify(data)}
Client Session: ${JSON.stringify(clientSession)}
Cookie: ${cookie || 'Empty'}
Origin: ${window.location.origin}
                `
                            });
                        }
                    } catch (e: any) {
                        setDebugInfo({
                            status: 'error',
                            message: 'Error verifying session',
                            details: e.message
                        });
                    }
                }} />

                <div className="mt-6 text-center text-sm text-zinc-600 dark:text-zinc-400">
                    Don&apos;t have an account?{' '}
                    <Link href="/auth/sign-up" className="text-blue-600 hover:underline font-medium">
                        Sign Up
                    </Link>
                </div>
            </div>

            {/* Full Screen Overlay for Debug Info */}
            {debugInfo && (
                <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/80 backdrop-blur-sm p-4">
                    <div className="bg-white dark:bg-zinc-900 max-w-lg w-full rounded-xl shadow-2xl p-6 border border-zinc-200 dark:border-zinc-800">
                        <div className="flex flex-col items-center text-center gap-4">
                            {debugInfo.status === 'verifying' && (
                                <Loader2 className="h-12 w-12 animate-spin text-blue-500" />
                            )}
                            {debugInfo.status === 'success' && (
                                <div className="h-12 w-12 rounded-full bg-green-100 flex items-center justify-center text-green-600 text-2xl">✓</div>
                            )}
                            {(debugInfo.status === 'failed' || debugInfo.status === 'error') && (
                                <div className="h-12 w-12 rounded-full bg-red-100 flex items-center justify-center text-red-600 text-2xl">!</div>
                            )}

                            <h2 className="text-xl font-bold">{debugInfo.message}</h2>

                            {debugInfo.details && (
                                <div className="w-full bg-zinc-100 dark:bg-zinc-950 p-4 rounded-lg text-left overflow-auto max-h-60 font-mono text-xs whitespace-pre-wrap break-all">
                                    {debugInfo.details}
                                </div>
                            )}

                            <div className="flex gap-2 w-full mt-2">
                                <button
                                    onClick={() => setDebugInfo(null)}
                                    className="flex-1 px-4 py-2 border border-zinc-300 dark:border-zinc-700 rounded hover:bg-zinc-100 dark:hover:bg-zinc-800"
                                >
                                    Close
                                </button>
                                {debugInfo.status === 'success' && (
                                    <button
                                        onClick={() => window.location.href = '/app'}
                                        className="flex-1 px-4 py-2 bg-blue-600 text-white rounded hover:bg-blue-700"
                                    >
                                        Go to App Now
                                    </button>
                                )}
                                {(debugInfo.status === 'failed' || debugInfo.status === 'error') && (
                                    <button
                                        onClick={() => window.location.reload()}
                                        className="flex-1 px-4 py-2 bg-zinc-800 text-white rounded hover:bg-zinc-900"
                                    >
                                        Reload
                                    </button>
                                )}
                            </div>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
}

'use client';
import { authClient } from '@/lib/auth-client';
import { useState, useEffect } from 'react';

export default function DebugPage() {
    const [data, setData] = useState<any>({});
    const [loading, setLoading] = useState(true);

    useEffect(() => {
        async function run() {
            const result: any = {};
            result.url = window.location.href;
            result.cookie = document.cookie;

            try {
                result.clientSession = await authClient.getSession();
            } catch (e: any) {
                result.clientError = e.message;
            }

            try {
                const res = await fetch('/api/auth/get-session');
                result.apiStatus = res.status;
                result.apiBody = await res.json();
            } catch (e: any) {
                result.apiError = e.message;
            }

            setData(result);
            setLoading(false);
        }
        run();
    }, []);

    if (loading) return <div>Loading debug info...</div>;

    return (
        <div className="p-8 font-mono text-sm whitespace-pre-wrap bg-white dark:bg-black text-black dark:text-white">
            <h1 className="text-xl font-bold mb-4">Debug Session</h1>
            {JSON.stringify(data, null, 2)}
        </div>
    );
}

